import heapq


def _ledger(data, sequence_first, original_tax):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(events):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        rev = event.get("revision", 0)
        key = ((seq, rev, pos) if sequence_first else (rev, pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        base = raw if original_tax else net
        tax = rounded(base * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_ledger(sequence_first, original_tax):
    return lambda data: _ledger(data, sequence_first, original_tax)


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    domains = [[-1] + [row["version"] for row in packages[name]] for name in names]
    best_vector = None
    best = None

    for values in product(*domains):
        chosen = {name: value for name, value in zip(names, values) if value != -1}
        if any(name not in chosen or not lo <= chosen[name] <= hi
               for name, (lo, hi) in roots.items()):
            continue
        if any(name in chosen and (chosen[name] in blocked.get(name, []) or
                                   chosen[name] != pins.get(name, chosen[name]))
               for name in names):
            continue
        rows = {name: {row["version"]: row for row in packages[name]} for name in names}
        done, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            if name not in chosen:
                return False
            active.add(name)
            row = rows[name][chosen[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = chosen.get(other, -1)
                if not dep["min"] <= version <= dep["max"] or not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        if not all(visit(name) for name in roots):
            continue
        if done != set(chosen):
            continue
        vector = tuple(chosen.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best = vector, chosen
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    available = [job for job in jobs if job["id"] not in blocked]
    if k > len(available) or not mandatory.issubset({j["id"] for j in available}):
        return {"error": "impossible"}

    for subset in combinations(available, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        ends = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            ends = [end for end in ends if end > job["start"]]
            ends.append(job["end"])
            if len(ends) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start = data["start"]
    initial = (source, initial_mask, 0)
    distance = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distance.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > data["coupons"]:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(2, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = mask | bits.get(nxt, 0)
                new_used = used + spend
                new_state = (nxt, new_mask, new_used)
                if arrival < distance.get(new_state, float("inf")):
                    distance[new_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, new_mask, new_used))
    return {"arrival": None}


